import json, copy
source = '''def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        sides = selected.setdefault(event['key'], {})
        side = event['side']
        epoch = event['epoch']
        digest = event['digest']
        current = sides.get(side)
        if current is None or epoch > current[0]:
            sides[side] = (epoch, {digest})
        elif epoch == current[0]:
            current[1].add(digest)
    result = {}
    for key, sides in selected.items():
        if any(len(digests) > 1 for epoch, digests in sides.values()):
            status = 'conflict'
        elif 'L' not in sides or 'R' not in sides:
            status = 'pending'
        elif sides['L'][0] != sides['R'][0]:
            status = 'pending'
        elif sides['L'][1] != sides['R'][1]:
            status = 'diverged'
        else:
            status = 'verified'
        result[key] = status
    return result
'''
