import json
source = "def audit(events, at):
    eligible = [event for event in events if event['seen'] <= at]
    selected = {}
    fences = {}
    for event in eligible:
        key = event['key']
        selected.setdefault(key, {})
        if event['kind'] == 'fence':
            pair = (key, event['side'])
            fences[pair] = max(fences.get(pair, 0), event['through'])
    for event in eligible:
        if event['kind'] != 'ack':
            continue
        key, side = event['key'], event['side']
        epoch, digest = event['epoch'], event['digest']
        if epoch <= fences.get((key, side), 0):
            continue
        sides = selected[key]
        current = sides.get(side)
        if current is None or epoch > current[0]:
            sides[side] = (epoch, {digest})
        elif epoch == current[0]:
            current[1].add(digest)
    result = {}
    for key, sides in selected.items():
        if not sides:
            status = 'withdrawn'
        elif any(len(digests) > 1 for epoch, digests in sides.values()):
            status = 'conflict'
        elif 'L' not in sides or 'R' not in sides:
            status = 'pending'
        elif sides['L'][0] != sides['R'][0]:
            status = 'pending'
        elif sides['L'][1] != sides['R'][1]:
            status = 'diverged'
        else:
            status = 'verified'
        result[key] = status
    return result
